pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        address ceo = c.ceoAddress();

        vm.deal(address(this), 1);
        c.seedMarket{value: 1}(1);

        vm.prank(ceo);
        c.DrugDealer();

        bool ok = false;
        try c.getFreeKilo() { ok = true; } catch { ok = false; }

        assertTrue(ok);
    }
}
